            + f'<div style="margin:12px 16px 0;background:var(--strip);color:var(--onStrip);padding:10px 12px;display:flex;gap:12px;align-items:center">{cv("mor", 48)}<span style="flex:1"><b style="font:600 15px Inter">Pelota</b><br>'
