def downloads():
    def dl(i, k, stage, pct, msg, acts, bad=False):
        segs = "".join(f'<i class="{"x" if bad and j == stage else ("d" if j <= stage and not (bad and j == stage) else "")}"></i>' for j in range(4))
        return (f'<li class="rw" style="grid-template-columns:26px 48px 1fr auto;align-items:start;padding:12px 0">{m(f"0{i}", "n")}{cv(k, 48)}<span><b>{A[k][0]}</b>{m(A[k][1] + " · lossless", "mu")}'
                f'<div class="track">{segs}</div><div style="display:grid;grid-template-columns:repeat(4,1fr);gap:4px;margin-top:3px" class="m mu"><span style="font-size:8.5px">Found</span><span style="font-size:8.5px">Loading</span><span style="font-size:8.5px">Import</span><span style="font-size:8.5px">Done</span></div>'
                f'<div style="font:400 13px Inter;margin-top:6px">{msg}</div><div style="display:flex;gap:6px;margin-top:6px">{acts}</div></span><span class="d" style="font-size:20px">{pct}</span></li>')
    tabs = '<div class="tabs m" style="margin-top:12px"><span class="on">Active <span class="sig">3</span></span><span>Done <span class="sig">14</span></span><span>Failed <span class="sig">1</span></span></div>'
    return (top() + head("Downloads", "3") + tabs + '<ul class="rows" style="padding:0 16px">' + dl(1, "hex", 1, "62", "2.1 MB/s · 4 of 7 songs", '<span class="btn s g">Use next source</span>')
            + dl(2, "ntr", 2, "90", "Importing into your library", "") + dl(3, "ele", 1, "!", "Stalled 15 s. No other source answered.", f'<span class="btn s">{ic("refresh")}Try again</span><span class="btn s g">Dismiss</span>', True) + "</ul>")


