# ------------------------------------------------------------------------------------------------ Sheets

def sheets():
    def menu(k, title, sub, opts):
        o = "".join(f'<div class="opt">{m(chr(65 + i), "sig")}<span><b style="{"color:var(--chartRedText)" if dz else ""}">{t}</b>{f"<small>{s}</small>" if s else ""}</span>{ic(n, "s")}</div>' for i, (t, s, n, dz) in enumerate(opts))
        return f'<div class="handle"></div><div class="shd">{cv(k, 72)}<div>{m(sub, "mu")}<h3 class="d" style="font-size:30px;line-height:28px;margin:4px 0">{title}</h3></div></div>{o}'
    pick = menu("hex", "Hex", "Pick 01 / 12 · Bark Psychosis", [("Why this pick?", "Three albums you play often lead here", "chev", False), ("Not this album", "It leaves your picks", "close", False), ("Never suggest this artist", "Bark Psychosis leaves every list", "ban", True)])
    song = menu("mor", "Pelota", "Song 05 / 10 · Khruangbin", [("Play next", "", "qadd", False), ("Add to queue", "", "queue", False), ("Go to album", "", "album", False), ("Go to artist", "", "place", False), ("Paths from this album", "", "path", False)])
    confirm = (f'<div class="handle"></div><div style="padding:0 16px">{m("Downloads · 03", "mu")}<h3 class="d" style="font-size:30px;margin:4px 0 8px">Dismiss Elevation?</h3>'
               f'<p style="margin:0;font:400 14px/21px Inter">It stops and leaves the list. Files already imported stay.</p><div style="display:flex;gap:8px;margin-top:16px"><span class="btn g" style="flex:1;justify-content:center">Keep</span><span class="btn danger" style="flex:1;justify-content:center">Dismiss</span></div></div>')
    snack = home_top() + '<div class="snack" style="bottom:128px">Hex removed from picks<u class="m">Undo</u></div>'
    fr = [frame("1 · Pick menu, options lettered", screen(home_top() + sheet(pick, 420), nodock=True)), frame("2 · Song menu", screen(queue() + sheet(song, 320), nodock=True)),
          frame("3 · Dismiss confirmation", screen(downloads() + sheet(confirm, 500), nodock=True)), frame("4 · Snackbar with Undo", screen(snack))]
    return kit.page("Index · Sheets and snackbar (Signal Blue)", HEAD, fr), 4

# ------------------------------------------------------------------------------------------------ Palettes, Components

def palettes():
    fr = [frame(f'{p["name"]} · {"day" if p["light"] else "night"}{" · default" if p.get("default") or p.get("defaultDark") else ""} ({p["id"]})', screen(home_top()), p["id"]) for p in TOKENS["palettes"]]
    return kit.page("Index · palettes (colour only; layout identical)", HEAD, fr), len(fr)


def components():
    sw = ""
    for p in TOKENS["palettes"]:
        cells = [(r, p[r]) for r in ("ink", "surface", "raised", "edge", "text", "textMuted", "accent", "control")] + [(r, p["tones"][r]) for r in ("strip", "stripProgress", "insight", "insightLabel")]
        sw += f'<div style="margin-bottom:10px"><b style="font:600 13px Inter">{p["name"]}</b><div style="display:grid;grid-template-columns:repeat(6,1fr);gap:4px;margin-top:4px">' + "".join(
            f'<div><i style="display:block;height:20px;background:{v};box-shadow:inset 0 0 0 1px rgba(0,0,0,.1)"></i><span style="font:500 8px/1.2 \'IBM Plex Mono\';display:block">{r}<br>{v}</span></div>' for r, v in cells) + "</div></div>"
    ty = "".join(f'<div style="font:{s["weight"]} {min(s["size"], 48)}px/{min(s["line"], 48)}px \'{s["face"]}\';letter-spacing:{s["tracking"]}em;{"text-transform:uppercase;" if s.get("caps") else ""}white-space:nowrap;overflow:hidden">{n} {s["size"]}</div>'
                 for n, s in TOKENS["type"].items() if n != "_about")
    icons = "".join(f'<div style="display:grid;justify-items:center;gap:2px">{ic(n)}<span style="font:500 7.5px \'IBM Plex Mono\'" class="mu">{n}</span></div>' for n in kit.ICONS)
    ctr = (f'<div style="display:flex;flex-wrap:wrap;gap:8px;align-items:center;padding:16px"><span class="btn">{ic("get")}Get album</span>{get_btn()}{get_btn("pending")}{get_btn("requested")}{get_btn("owned")}{get_btn("failed")}'
           f'<span class="btn g">Ghost</span><span class="btn danger s">Danger</span><span class="tag">FLAC 16/44.1</span><i class="sw on"></i><i class="sw"></i></div>'
           f'{head("Head", "12", ["Picks", "New", "Played"])}<section class="sec">{sh("Section", "meta", "All →")}<ul class="rows">{rw("01", cv("lst", 48), "Row title", "Data · line", m("14 plays", "mu"))}</ul></section>')
    fr = [frame("Colour tokens, all four palettes", f'<div style="padding:14px">{sw}</div>'), frame("Type scale (tokens.json → type; capped at 48 here)", f'<div style="padding:14px;display:grid;gap:4px">{ty}</div>'),
          frame("Controls, head, section, row; dock", f'<div class="body">{ctr}</div>' + dock(0)),
          frame(f"{len(kit.ICONS)} icons, 2 stroke, square caps, mitred (icons/)", f'<div style="padding:14px;display:grid;grid-template-columns:repeat(6,1fr);gap:10px 4px">{icons}</div>')]
    return kit.page("Index · Components", HEAD, fr), 4


